import subprocess
import psutil
import time

def task_func(process_name: str) -> str:
    # Check if the process is running
    process_found = False
    for proc in psutil.process_iter(['name']):
        if proc.info['name'] == process_name:
            process_found = True
            try:
                proc.terminate()  # Terminate the process
                proc.wait(timeout=5)  # Wait for the process to terminate
            except psutil.NoSuchProcess:
                pass  # Process is already terminated
            except psutil.TimeoutExpired:
                proc.kill()  # Force kill if it doesn't terminate gracefully
            break

    if not process_found:
        # If process not found, start it
        subprocess.Popen([process_name])
        return f"Process not found. Starting {process_name}."
    else:
        # If process found and terminated, restart it
        subprocess.Popen([process_name])
        return f"Process found. Restarting {process_name}."

