import json
import os
import re

def task_func(
    file_path,
    attribute,
    INPUT_JSON={
        "type": "object",
        "properties": {
            "name": {"type": str},  
            "age": {"type": int},   
            "email": {"type": str}  
        },
        "required": ["name", "age", "email"]
    },
    EMAIL_REGEX=r"^[a-z0-9]+[\._]?[a-z0-9]+[@]\w+[.]\w{2,3}$"):

    # Check if the file exists
    if not os.path.exists(file_path):
        raise ValueError("The file does not exist")

    # Load JSON data from file
    with open(file_path, 'r') as file:
        try:
            data = json.load(file)
        except json.JSONDecodeError:
            raise ValueError("Invalid JSON format")

    # Validate required attributes
    for req_attr in INPUT_JSON["required"]:
        if req_attr not in data:
            raise ValueError(f"Missing required attribute: {req_attr}")

    # Validate types of attributes
    for key, value in INPUT_JSON["properties"].items():
        if key in data and not isinstance(data[key], value["type"]):
            raise ValueError(f"Invalid type for attribute: {key}. Expected {value['type'].__name__}, got {type(data[key]).__name__}")

    # Validate email with regex
    if "email" in data:
        if not re.match(EMAIL_REGEX, data["email"]):
            raise ValueError("Invalid email format")

    # Retrieve the specified attribute
    if attribute in data:
        return data[attribute]
    else:
        raise ValueError(f"Attribute {attribute} not found in the JSON file")

