import re
import pandas as pd

STOPWORDS = ["Those", "are", "the", "words", "to", "ignore"]

def task_func(text):
    sentences = re.split(r'(?<=\w[.!?]) +', text)
    sentence_counts = {}

    for index, sentence in enumerate(sentences):
        words = re.findall(r'\b\w+\b', sentence)
        count = len([word for word in words if word not in STOPWORDS])

        if count > 0:
            sentence_counts[f"Sentence {index + 1}"] = count

    return pd.Series(sentence_counts)

