import hashlib
import base64
import binascii
from django.http import HttpResponseBadRequest, HttpResponse

def task_func(data):
    """
    This method is designed to handle the authentication process in a web application context.
    """
    try:
        if not isinstance(data, dict) or 'username' not in data or 'password' not in data:
            return HttpResponseBadRequest('Bad Request.')

        username = data['username']
        password = data['password']

        if username != 'admin':
            return HttpResponse('Login failed.', status=401)

        # Decode the base64-encoded SHA-256 hash
        try:
            decoded_password = base64.b64decode(password)
        except (binascii.Error, UnicodeDecodeError):
            return HttpResponseBadRequest('Bad Request.')

        # Recalculate the hash of the predefined password
        correct_hash = hashlib.sha256('password'.encode()).digest()

        if decoded_password == correct_hash:
            return HttpResponse('Login successful.', status=400)
        else:
            return HttpResponse('Login failed.', status=401)

    except (KeyError, ValueError):
        return HttpResponseBadRequest('Bad Request.')

