from flask import Flask, render_template, redirect, url_for
from flask_login import LoginManager, UserMixin, login_user, login_required, logout_user, current_user
from flask_wtf import FlaskForm
from wtforms import StringField, PasswordField, SubmitField
from wtforms.validators import DataRequired, Length
from werkzeug.security import generate_password_hash, check_password_hash

class LoginForm(FlaskForm):
    username = StringField('Username', validators=[DataRequired(), Length(min=4, max=25)])
    password = PasswordField('Password', validators=[DataRequired(), Length(min=8, max=80)])
    submit = SubmitField('Log In')

login_manager = LoginManager()

class User(UserMixin):
    def __init__(self, id, username, password_hash):
        self.id = id
        self.username = username
        self.password_hash = password_hash

    def check_password(self, password):
        return check_password_hash(self.password_hash, password)

users = {
    "testuser": User("1", "testuser", generate_password_hash("password123"))
}

@login_manager.user_loader
def load_user(user_id):
    for user in users.values():
        if user.id == user_id:
            return user
    return None

def task_func(secret_key, template_folder):
    app = Flask(__name__, template_folder=template_folder)
    app.config['SECRET_KEY'] = secret_key
    login_manager.init_app(app)

    @app.route('/login', methods=['GET', 'POST'])
    def login():
        form = LoginForm()
        if form.validate_on_submit():
            user = users.get(form.username.data)
            if user and user.check_password(form.password.data):
                login_user(user)
                return redirect(url_for('protected'))
        return render_template('login.html', form=form)

    @app.route('/logout')
    @login_required
    def logout():
        logout_user()
        return redirect(url_for('login'))

    @app.route('/protected')
    @login_required
    def protected():
        return f'Hello, {current_user.username}! This is a protected page.'

    return app

import numpy as np
import pandas as pd

def task_func(products, n_samples=100, sales_lower=50, sales_upper=200, profit_margin_min=0.1, profit_margin_max=0.5, random_seed=42):
    if not isinstance(products, list) or not all(isinstance(p, str) for p in products):
        raise TypeError("Products must be a list of strings.")
    if not isinstance(n_samples, int) or n_samples <= 0:
        raise ValueError("n_samples must be a positive integer.")
    if not isinstance(sales_lower, (int, float)) or not isinstance(sales_upper, (int, float)):
        raise TypeError("Sales bounds must be numeric.")
    if not isinstance(profit_margin_min, (int, float)) or not isinstance(profit_margin_max, (int, float)):
        raise TypeError("Profit margins must be numeric.")
    if sales_lower > sales_upper:
        raise ValueError("sales_lower cannot be greater than sales_upper.")

    np.random.seed(random_seed)
    product_choices = np.random.choice(products, n_samples)
    sales = np.random.randint(sales_lower, sales_upper + 1, n_samples)
    profit_margins = np.random.uniform(profit_margin_min, profit_margin_max, n_samples)
    profits = sales * profit_margins

    df = pd.DataFrame({
        'Product': product_choices,
        'Sales': sales,
        'Profit': profits
    })

    aggregated = df.groupby('Product').sum().reset_index()
    sorted_aggregated = aggregated.sort_values(by='Profit', ascending=False, ignore_index=True)

    return sorted_aggregated

