import socket
from ipaddress import IPv4Network
from threading import Thread

def task_func(ip_range, port):
    def check_port(ip, port, result_dict):
        with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
            s.settimeout(1)
            try:
                s.connect((ip, port))
                result_dict[ip] = True
            except (socket.timeout, ConnectionRefusedError):
                result_dict[ip] = False

    result = {}
    threads = []

    for ip in IPv4Network(ip_range, strict=False):
        thread = Thread(target=check_port, args=(str(ip), port, result))
        threads.append(thread)
        thread.start()

    for thread in threads:
        thread.join()

    return result

import pandas as pd
import numpy as np

DEFAULT_COLUMNS = ['Element', 'Count']

def task_func(elements, include_index=False):
    data = {
        'Element': elements,
        'Count': [len(element) for element in elements]
    }

    df = pd.DataFrame(data)

    if include_index:
        df.reset_index(inplace=True)
        df.rename(columns={'index': 'Index'}, inplace=True)
        df = df[['Index'] + DEFAULT_COLUMNS]
    else:
        df = df[DEFAULT_COLUMNS]

    return df

