def task_func(ip_address):
    import re
    import json

    # Constants
    IP_REGEX = r'[0-9]+(?:\.[0-9]+){3}'

    try:
        data = json.loads(ip_address)
        ip = data.get("ip", "")
        if re.match(IP_REGEX, ip):
            return ip
        else:
            return 'Invalid IP address received'
    except json.JSONDecodeError:
        return 'Invalid IP address received'

