import pandas as pd
import numpy as np
from random import choice, randint
import string

# Constants
DATA_TYPES = [str, int, float, list, tuple, dict, set]

def random_data(dtype):
    if dtype == str:
        return ''.join(choice(string.ascii_lowercase) for _ in range(5))
    elif dtype == int:
        return randint(0, 9)
    elif dtype == float:
        return float(randint(0, 9))
    elif dtype == list:
        return [randint(0, 9) for _ in range(randint(1, 5))]
    elif dtype == tuple:
        return tuple(randint(0, 9) for _ in range(randint(1, 5)))
    elif dtype == dict:
        return {randint(0, 9): randint(0, 9) for _ in range(randint(1, 5))}
    elif dtype == set:
        return set(randint(0, 9) for _ in range(randint(1, 5)))

def task_func(rows, columns):
    data = {}
    for col_idx in range(columns):
        dtype = choice(DATA_TYPES)
        col_name = f'col{col_idx}'
        data[col_name] = [random_data(dtype) for _ in range(rows)]
    return pd.DataFrame(data)

