import unittest
import random
LETTERS = ['a', 'b', 'c', 'd', 'e', 'f', 'g', 'h', 'i', 'j']
class TestCases(unittest.TestCase):
    def test_basic_functionality(self):
        random.seed(0)
        result = task_func(3, 5)
        self.assertLessEqual(len(result), 3)
        for key in result:
            self.assertIn(key, LETTERS)
            self.assertEqual(result[key], [1, 2, 3, 4, 5])
    def test_no_keys(self):
        random.seed(0)
        result = task_func(0, 5)
        self.assertEqual(result, {})
    def test_no_values(self):
        random.seed(0)
        result = task_func(3, 0)
        for key in result:
            self.assertEqual(result[key], [])
    def test_large_input(self):
        random.seed(0)
        result = task_func(10, 1000)
        for key in result:
            self.assertIn(key, LETTERS)
            self.assertEqual(len(result[key]), 1000)
    def test_max_keys(self):
        random.seed(0)
        result = task_func(len(LETTERS), 5)
        for key in result:
            self.assertIn(key, LETTERS)
            self.assertEqual(result[key], [1, 2, 3, 4, 5])

import unittest
from faker import Faker
fake = Faker()
class TestCases(unittest.TestCase):
    def test_empty_string(self):
        self.assertEqual(task_func(""), {})
    def test_single_word(self):
        word = fake.word()
        self.assertEqual(task_func(word)[word], 1)
    def test_multiple_words(self):
        sentence = fake.sentence()
        expected_result = {}
        for word in sentence.split():
            expected_result[word] = expected_result.get(word, 0) + 1
        self.assertEqual(len(task_func(sentence)), len(expected_result))
    def test_case_sensitivity(self):
        sentence = 'Apple apple'
        self.assertEqual(task_func(sentence), {"Apple": 1, "apple": 1})
    def test_punctuation_inclusion(self):
        sentence = 'apple, apple; banana!'
        self.assertEqual(task_func(sentence), {"apple": 2, "banana": 1})
    def test_numeric_and_special_characters(self):
        sentence = '123 $%^& 123'
        self.assertEqual(task_func(sentence), {'123': 2})

import unittest
import requests_mock
import requests
# Constants
SUCCESS_RESPONSE = {
    'status': 'success',
    'message': 'Data received successfully.'
}
ERROR_RESPONSE = {
    'status': 'error',
    'message': 'Invalid data received.'
}
class TestCases(unittest.TestCase):
    @requests_mock.mock()
    def test_invalid_content_type_header(self, m):
        # Mock the POST request to return a 400 status code for invalid content type
        m.post("http://testserver/", status_code=400, json=ERROR_RESPONSE)
        response = requests.post("http://testserver/", headers={"Content-Type": "text/plain"})
        self.assertEqual(response.json(), ERROR_RESPONSE)
        self.assertEqual(response.status_code, 400)
    @requests_mock.mock()
    def test_missing_data_in_request(self, m):
        # Mock the POST request to return a 400 status code for missing 'data' key
        m.post("http://testserver/", status_code=400, json=ERROR_RESPONSE)
        response = requests.post("http://testserver/", json={"wrong_key": "value"})
        self.assertEqual(response.json(), ERROR_RESPONSE)
        self.assertEqual(response.status_code, 400)
    @requests_mock.mock()
    def test_valid_post_request(self, m):
        m.post("http://testserver/", text=json.dumps(SUCCESS_RESPONSE))
        response = requests.post("http://testserver/", json={"data": "value"})
        self.assertEqual(response.json(), SUCCESS_RESPONSE)
        self.assertEqual(response.status_code, 200)
    @requests_mock.mock()
    def test_response_content_type(self, m):
        # Mock the POST request and explicitly set the 'Content-Type' header
        headers = {'Content-Type': 'application/json'}
        m.post("http://testserver/", json=SUCCESS_RESPONSE, headers=headers)
        response = requests.post("http://testserver/", json={"data": "value"})
        self.assertEqual(response.headers["Content-Type"], "application/json")
    @requests_mock.mock()
    def test_incorrect_http_method(self, m):
        m.get("http://testserver/", status_code=405)
        response = requests.get("http://testserver/")
