import csv
import re
from collections import Counter

def task_func(file_path, regex_pattern=r'\(.+?\)|\w+|[\W_]+'):
    matches = Counter()
    with open(file_path, mode='r', newline='') as file:
        reader = csv.reader(file)
        for row in reader:
            for column in row:
                matches.update(re.findall(regex_pattern, column))
    return dict(matches)

