import pandas as pd
import os

def task_func(original_file_location="test.xlsx", new_file_location="new_test.xlsx", sheet_name="Sheet1"):
    # Check if the original Excel file exists
    if not os.path.isfile(original_file_location):
        raise FileNotFoundError(f"The file {original_file_location} does not exist.")

    # Read data from the original Excel file
    try:
        data = pd.read_excel(original_file_location, sheet_name=sheet_name)
    except ValueError as e:
        if "Worksheet named" in str(e):
            raise ValueError(f"The sheet named {sheet_name} does not exist in the workbook.")
        else:
            raise e

    # Save the data to a new Excel file
    data.to_excel(new_file_location, index=False, sheet_name=sheet_name)

    # Read data from the newly created Excel file to verify
    new_data = pd.read_excel(new_file_location, sheet_name=sheet_name)

    return new_data

