import json
from pathlib import Path

def task_func(directory, string):
    result = []

    def search_json(data, search_string):
        if isinstance(data, dict):
            for key, value in data.items():
                if key == search_string or search_json(value, search_string):
                    return True
        elif isinstance(data, list):
            for item in data:
                if search_json(item, search_string):
                    return True
        elif isinstance(data, str) and data == search_string:
            return True
        return False

    for path in Path(directory).rglob('*.json'):
        try:
            with open(path, 'r', encoding='utf-8') as file:
                data = json.load(file)
                if search_json(data, string):
                    result.append(str(path))
        except (json.JSONDecodeError, IOError):
            continue

    return result

