import subprocess
import psutil
import time
import os

def task_func(script_path: str, timeout=10) -> dict:
    if not os.path.exists(script_path):
        return {'CPU Usage': 0.0, 'Memory Usage': 0}

    start_time = time.time()
    cpu_usage = 0.0
    mem_usage = 0

    try:
        with subprocess.Popen(
            ['bash', script_path],
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE
        ) as proc:
            proc_pid = proc.pid
            while True:
                try:
                    proc_status = psutil.Process(proc_pid)
                    cpu_usage += proc_status.cpu_percent(interval=0.1)
                    mem_usage += proc_status.memory_info().rss
                    if time.time() - start_time > timeout:
                        proc.kill()
                        break
                    if proc.poll() is not None:
                        break
                except psutil.NoSuchProcess:
                    break
    except Exception as e:
        pass

    return {'CPU Usage': cpu_usage, 'Memory Usage': mem_usage}

