from collections import defaultdict
import numpy as np
import matplotlib.pyplot as plt

def task_func(data):
    if not isinstance(data, list) or not all(isinstance(d, dict) for d in data):
        raise TypeError("The input must be a list of dictionaries.")
    if not data:
        raise ValueError("The input data cannot be empty.")

    stats = defaultdict(lambda: {'mean': 0.0, 'std': 0.0})

    for d in data:
        for key, value in d.items():
            if not isinstance(value, (int, float)):
                raise TypeError(f"All values must be numeric. Found {type(value)} for key {key}.")
            stats[key]['values'] = stats[key].get('values', []) + [value]

    axes = []
    for key, values in stats.items():
        mean_val = np.mean(values['values'])
        std_val = np.std(values['values'])
        stats[key]['mean'] = mean_val
        stats[key]['std'] = std_val

        fig, ax = plt.subplots()
        ax.bar(['mean', 'std'], [mean_val, std_val], color=['blue', 'red'])
        ax.set_title(f"Statistics of {key}")
        ax.set_ylabel('Value')
        axes.append(ax)

    return ({key: {'mean': stats[key]['mean'], 'std': stats[key]['std']} for key in stats}, axes)

import json
import pandas as pd
import numpy as np
from collections import defaultdict

def task_func(input_file="data.json"):
    with open(input_file, 'r') as f:
        data = json.load(f)

    # Dictionary to store lists of numeric values for each key
    num_values = defaultdict(list)

    for record in data:
        for key, value in record.items():
            if isinstance(value, (int, float)):
                num_values[key].append(value)

    # Calculate mean and median for each key
    results = {}
    for key, values in num_values.items():
        if values:
            results[key] = {
                'mean': np.mean(values),
                'median': np.median(values)
            }
        else:
            results[key] = {
                'mean': np.nan,
                'median': np.nan
            }

    # Convert to DataFrame
    df = pd.DataFrame.from_dict(results, orient='index')

    # Sort by variable names
    df.sort_index(inplace=True)

    return df

