import json

def task_func(f):
    spec = inspect.getfullargspec(f)
    func_name = f.__name__
    is_lambda = isinstance(f, types.LambdaType) and f.__name__ == "<lambda>"
    annotations = {k: repr(v) for k, v in spec.annotations.items()}

    func_spec = {
        'name': func_name,
        'args': spec.args,
        'defaults': spec.defaults if spec.defaults else (),
        'annotations': annotations,
        'is_lambda': is_lambda
    }

    return json.dumps(func_spec)

import os
import pathlib
from hashlib import md5
import unicodedata

def task_func(directory):
    """
    Processes all files within the specified directory, normalizes their filenames to ASCII,
    calculates their MD5 hashes, and retrieves their sizes. It returns a dictionary where
    each key is the normalized file name and each value is another dictionary with the file's size
    and MD5 hash. This method is useful for file integrity checks and file organization tasks.

    Parameters:
    directory (str): The directory path whose files are to be analyzed.

    Returns:
    dict: A dictionary where each key is a normalized file name, and the value is a dictionary
          containing the 'Size' (in bytes) and 'MD5 Hash' of the file.
    """
    def normalize_filename(filename):
        return unicodedata.normalize('NFKD', filename).encode('ascii', 'ignore').decode('ascii')

    def file_md5(filepath):
        hash_md5 = md5()
        with open(filepath, "rb") as f:
            for chunk in iter(lambda: f.read(4096), b""):
                hash_md5.update(chunk)
        return hash_md5.hexdigest()

    result = {}
    path = pathlib.Path(directory)

    for filepath in path.iterdir():
        if filepath.is_file():
            normalized_name = normalize_filename(filepath.name)
            file_size = filepath.stat().st_size
            file_hash = file_md5(filepath)
            result[normalized_name] = {'Size': file_size, 'MD5 Hash': file_hash}

    return result

import unicodedata
import requests

URL = 'https://api.github.com/users/'

def task_func(username):
    response = requests.get(URL + username)
    response.raise_for_status()

    data = response.json()
    normalized_data = {}

    for key, value in data.items():
        if isinstance(value, str):
            normalized_value = unicodedata.normalize('NFKD', value).encode('ascii', 'ignore').decode('ascii')
            normalized_data[key] = normalized_value
        else:
            normalized_data[key] = value

    return normalized_data

