import os
import re
import hashlib

OUTPUT_DIR = './output'

def task_func(directory: str, pattern: str = r"(?<!Distillr)\\AcroTray\.exe") -> dict:
    matches = {}
    compiled_pattern = re.compile(pattern)

    for root, _, files in os.walk(directory):
        for file_name in files:
            if compiled_pattern.search(file_name):
                file_path = os.path.join(root, file_name)
                with open(file_path, 'rb') as file:
                    file_data = file.read()
                    sha256_hash = hashlib.sha256(file_data).hexdigest()
                    matches[file_path] = sha256_hash

    return matches

import re
import pandas as pd
import numpy as np

# Constants
DATA_PATTERN = r'>\d+\.\d+<'

def task_func(dataframe, data_pattern=DATA_PATTERN):
    def extract_number(cell):
        matches = re.findall(data_pattern, cell)
        if matches:
            # Strip '>' and '<' and convert to float
            return float(matches[0][1:-1])
        else:
            return np.nan

    return dataframe.applymap(extract_number)

