import numpy as np
import pandas as pd
from datetime import datetime

# Constants
DATE_FORMAT = '%Y-%m-%d %H:%M:%S'

def task_func(result):
    from_user_values = []

    for entry in result:
        if "from_user" in entry:
            value = entry["from_user"]
            if isinstance(value, (int, float)):
                from_user_values.append(value)
            else:
                raise ValueError("Non-numeric 'from_user' value found.")

    if not from_user_values:
        stats = {
            'mean': np.nan,
            'median': np.nan,
            'min': np.nan,
            'max': np.nan,
            'std': np.nan,
        }
    else:
        from_user_array = np.array(from_user_values)
        stats = {
            'mean': np.mean(from_user_array),
            'median': np.median(from_user_array),
            'min': np.min(from_user_array),
            'max': np.max(from_user_array),
            'std': np.std(from_user_array, ddof=0),
        }

    current_time = datetime.now().strftime(DATE_FORMAT)
    stats['current_time'] = current_time

    return pd.Series(stats)

