import json
import re
from collections import Counter

# Constants
REPLACE_NONE = "None"

def task_func(json_str):
    # Load JSON data into a dictionary
    data = json.loads(json_str)

    # Function to recursively process the data
    def process_value(val):
        if val is None:
            return None
        elif isinstance(val, str):
            # Replace email with REPLACE_NONE
            if re.match(r"[^@]+@[^@]+\.[^@]+", val):
                return REPLACE_NONE
            return val
        elif isinstance(val, dict):
            return {k: v for k, v in ((k, process_value(v)) for k, v in val.items()) if v is not None}
        elif isinstance(val, list):
            return [process_value(item) for item in val if process_value(item) is not None]
        else:
            return val

    # Process data to remove None values and replace emails
    processed_data = process_value(data)

    # Flatten the processed data for counting
    def flatten_dict(d):
        items = []
        for v in d.values():
            if isinstance(v, dict):
                items.extend(flatten_dict(v))
            elif isinstance(v, list):
                items.extend(v)
            else:
                items.append(v)
        return items

    flattened_values = flatten_dict(processed_data)

    # Count the frequency of each unique value
    value_counts = Counter(flattened_values)

    return {
        'data': processed_data,
        'value_counts': value_counts
    }

