import time
import random

def task_func(iterations=5, min_delay=1.0, max_delay=2.0, seed=None):
    if not isinstance(iterations, int) or iterations <= 0:
        raise ValueError("iterations must be a positive integer")
    if not (isinstance(min_delay, float) or isinstance(min_delay, int)) or min_delay <= 0:
        raise ValueError("min_delay must be a positive float")
    if not (isinstance(max_delay, float) or isinstance(max_delay, int)) or max_delay <= 0:
        raise ValueError("max_delay must be a positive float")
    if min_delay > max_delay:
        raise ValueError("min_delay must be less than or equal to max_delay")

    if seed is not None:
        random.seed(seed)

    messages = []
    total_delay = 0.0

    for _ in range(iterations):
        delay = random.uniform(min_delay, max_delay)
        time.sleep(delay)
        messages.append(f"{delay:.2f} seconds have passed")
        total_delay += delay

    return messages, total_delay

import pandas as pd
from statistics import mean

def task_func(df: pd.DataFrame) -> dict:
    if 'Name' not in df.columns or 'Score' not in df.columns:
        raise ValueError("DataFrame must contain 'Name' and 'Score' columns.")

    def generate_averages(name, scores):
        yield (name, mean(scores))

    result = {}
    grouped = df.groupby('Name')['Score']
    for name, scores in grouped:
        result[name] = generate_averages(name, scores)

    return result

