        seed(rng_seed)

    student_cycle = cycle(students)
    grades = [randint(grade_range.start, grade_range.stop - 1) for _ in range(n_grades)]
    selected_students = [next(student_cycle) for _ in range(n_grades)]

    data = {'Student': selected_students, 'Grade': grades}
    return pd.DataFrame(data)

import numpy as np
import itertools

def task_func(data_list, file_name):
    def safe_float(x):
        try:
            return float(x)
        except (ValueError, TypeError):
            return np.nan

    if not data_list:
        with open(file_name, 'w') as f:
            pass
        return []

    num_positions = max(len(t) for t in data_list) - 1
    values_per_position = [[] for _ in range(num_positions)]

    for tup in data_list:
        for i, value in enumerate(itertools.islice(tup, 1, None)):
            values_per_position[i].append(safe_float(value))

    means = [np.nanmean(values) for values in values_per_position]

    with open(file_name, 'w') as f:
        for i, mean in enumerate(means, start=1):
            f.write(f"Position {i}: {mean}\n")

    return means

from itertools import zip_longest
from scipy.spatial import distance

def task_func(points):
    if not points or len(points) < 2:
        return []

    processed_points = [(pt[0], pt[0]) if len(pt) == 1 else pt for pt in points]

    distances = []
    for p1, p2 in zip_longest(processed_points, processed_points[1:]):
        if p2 is None:
            break
        distances.append(distance.euclidean(p1, p2))

    return distances

import pandas as pd
import random

def task_func(data, columns=['Name', 'Age', 'Occupation'], fill_missing=False, num_range=(0, 100), seed=None):
    # Set the seed for reproducibility
    if seed is not None:
        random.seed(seed)

    # Create a DataFrame with None filled for missing values
    df = pd.DataFrame(data, columns=columns)

    # Fill missing numeric values with random numbers if fill_missing is True
    if fill_missing:
        for column in columns:
            if df[column].dtype == 'float64' or df[column].dtype == 'int64':
                df[column] = df[column].apply(
                    lambda x: x if pd.notnull(x) else random.uniform(*num_range)
                )

    return df

import pandas as pd
import numpy as np
from scipy.stats import chi2_contingency

def task_func(data, col1, col2):
    if data.empty:
        raise ValueError("DataFrame is empty.")
    if col1 not in data.columns or col2 not in data.columns:
        raise ValueError("Specified columns are not in DataFrame.")
    if data[col1].dtype not in [np.object, 'category'] or data[col2].dtype not in [np.object, 'category']:
        raise TypeError("Columns must contain categorical data.")

    contingency_table = pd.crosstab(data[col1], data[col2])
    if contingency_table.size < 2:
        raise ValueError("Both columns must have multiple categories.")
    if (contingency_table < 5).any().any():
        raise ValueError("Some categories have less than 5 observations.")

    chi2, p, _, _ = chi2_contingency(contingency_table)
    return p

