import os
import random
import pandas as pd

def task_func(data_dir,
              csv_files=['file1.csv', 'file2.csv', 'file3.csv'],
              seed=None):
    # Set the random seed if provided
    if seed is not None:
        random.seed(seed)

    # Randomly select one of the CSV files
    selected_file = random.choice(csv_files)
    file_path = os.path.join(data_dir, selected_file)

    # Read the CSV file into a DataFrame
    try:
        df = pd.read_csv(file_path)
    except pd.errors.EmptyDataError:
        return selected_file, pd.DataFrame()

    # If the DataFrame is empty, return it immediately
    if df.empty:
        return selected_file, df

    # Randomly sample a certain number of rows from the DataFrame
    if seed is not None:
        sampled_df = df.sample(n=min(len(df), 10), random_state=seed)
    else:
        sampled_df = df.sample(n=min(len(df), 10))

    return selected_file, sampled_df

