import numpy as np
from scipy import stats

def task_func(word: str) -> (np.ndarray, float):
    differences = np.diff([ord(c) for c in word])
    if len(differences) == 0:
        entropy = 0.0
    else:
        entropy = stats.entropy(np.histogram(differences, bins=len(set(differences)))[0], base=np.e)
    return differences, entropy

