import random
import re

def task_func(target_words, n_sentences, vocabulary):
    if n_sentences < 0:
        raise ValueError("n_sentences must not be negative")
    if not vocabulary:
        raise ValueError("vocabulary must not be empty")

    processed_target_words = [' '.join(re.split(r'\s+', word.strip().lower())) for word in target_words]

    sentences = []

    for _ in range(n_sentences):
        sentence = ' '.join(random.choices(vocabulary, k=10)).lower()
        for word in processed_target_words:
            pattern = re.compile(re.escape(word), re.IGNORECASE)
            sentence = pattern.sub(lambda m: m.group(0).replace(' ', '_'), sentence)
        sentences.append(sentence)

    return sentences

import random
import re

def task_func(text, seed=None):
    if seed is not None:
        random.seed(seed)

    def scramble(word):
        if len(word) > 3:
            middle = list(word[1:-1])
            random.shuffle(middle)
            return word[0] + ''.join(middle) + word[-1]
        return word

    words = re.findall(r'\b\w+\b', text)
    scrambled_words = {word: scramble(word) for word in words}

    def replace_word(match):
        word = match.group(0)
        return scrambled_words.get(word, word)

    return re.sub(r'\b\w+\b', replace_word, text)

import string
import random

def task_func(text, seed=None):
    if seed is not None:
        random.seed(seed)

    transformed_text = []

    for char in text:
        if char.isalpha():
            if char.islower():
                transformed_char = random.choice(string.ascii_lowercase)
            else:
                transformed_char = random.choice(string.ascii_uppercase)
            transformed_text.append(transformed_char)
        else:
            transformed_text.append(char)

    return ''.join(transformed_text)

