import shutil
import pathlib
from typing import List, Tuple

def task_func(source_path: str, destination_path: str) -> Tuple[str, List[str]]:
    source = pathlib.Path(source_path)
    destination = pathlib.Path(destination_path)

    if not source.exists() or not source.is_dir():
        raise ValueError(f"Source path '{source_path}' does not exist or is not a directory.")

    if not destination.exists():
        destination.mkdir(parents=True)

    files_copied = []
    for item in source.iterdir():
        if item.is_file():
            shutil.copy2(item, destination)
            files_copied.append(item.name)

    return (source.name, files_copied)

import pandas as pd
from datetime import datetime
import random
import matplotlib.pyplot as plt

def task_func(start_date, end_date, num_series, seed=None):
    if seed is not None:
        random.seed(seed)

    start_date = datetime.strptime(start_date, "%Y-%m-%d")
    end_date = datetime.strptime(end_date, "%Y-%m-%d")

    if start_date > end_date:
        raise ValueError("start_date must be earlier than end_date.")
    if num_series < 1:
        raise ValueError("num_series must be at least 1.")

    date_range = pd.date_range(start=start_date, end=end_date)
    data = {
        f'series_{i+1}': [random.randint(0, 100) for _ in date_range]
        for i in range(num_series)
    }

    df = pd.DataFrame(data, index=date_range)

    ax = df.plot(title="Random Time Series", xlabel="Date", ylabel="Value")
    plt.show()

    return df, ax

