import os
import re
from pathlib import Path

def task_func(dir_path: str, predicates: list) -> dict:
    if not os.path.isdir(dir_path):
        raise FileNotFoundError(f"The specified directory does not exist: {dir_path}")

    # Deduplicate predicates and filter supported ones
    predicates = set(predicates)
    valid_predicates = {'is_file', 'is_dir', 'has_special_chars', 'has_numbers'}
    predicates = predicates.intersection(valid_predicates)

    if not predicates:
        raise ValueError("No valid predicates provided.")

    results = {}

    for item in os.listdir(dir_path):
        item_path = Path(dir_path) / item
        item_results = {}

        if 'is_file' in predicates:
            item_results['is_file'] = item_path.is_file()

        if 'is_dir' in predicates:
            item_results['is_dir'] = item_path.is_dir()

        if 'has_special_chars' in predicates:
            name_no_ext = item_path.stem
            item_results['has_special_chars'] = bool(re.search(r'[^a-zA-Z0-9_]', name_no_ext))

        if 'has_numbers' in predicates:
            item_results['has_numbers'] = bool(re.search(r'\d', item_path.stem))

        results[item] = item_results

    return results

