import random
import string

def task_func(length: int, predicates: list, seed: int = None):
    if length < 0:
        raise ValueError("Length cannot be negative")

    valid_predicates = {'has_uppercase', 'has_lowercase', 'has_special_chars', 'has_numbers'}
    predicates = set(predicates)  # Deduplicate predicates
    if not predicates.issubset(valid_predicates):
        raise KeyError("Invalid predicates found")

    if seed is not None:
        random.seed(seed)

    chars = string.ascii_letters + string.digits + string.punctuation
    random_text = ''.join(random.choices(chars, k=length))

    characteristics = {}
    if 'has_uppercase' in predicates:
        characteristics['has_uppercase'] = any(c.isupper() for c in random_text)
    if 'has_lowercase' in predicates:
        characteristics['has_lowercase'] = any(c.islower() for c in random_text)
    if 'has_special_chars' in predicates:
        characteristics['has_special_chars'] = any(c in string.punctuation for c in random_text)
    if 'has_numbers' in predicates:
        characteristics['has_numbers'] = any(c.isdigit() for c in random_text)

    return random_text, characteristics

