import urllib.request
import zipfile
import os
import urllib.error

def task_func(
    url: str,
    save_path: str = "downloaded_file.zip",
    extract_path: str = "extracted_files",
) -> str:
    try:
        # Download the file from the given URL
        urllib.request.urlretrieve(url, save_path)
    except urllib.error.URLError as e:
        return f"URL Error: {e.reason}"
    except Exception as e:
        return f"Download Error: {e}"

    try:
        # Create the extraction path if it does not exist
        os.makedirs(extract_path, exist_ok=True)

        # Extract the downloaded file
        with zipfile.ZipFile(save_path, 'r') as zip_ref:
            zip_ref.extractall(extract_path)
    except zipfile.BadZipFile:
        return "Error: Bad ZIP file"
    except FileNotFoundError:
        return "Error: File not found"
    except Exception as e:
        return f"File I/O Error: {e}"
    finally:
        # Attempt to delete the downloaded ZIP file
        try:
            if os.path.exists(save_path):
                os.remove(save_path)
        except Exception as e:
            return f"Cleanup Error: {e}"

    return extract_path

