from bs4 import BeautifulSoup
import pandas as pd

def task_func(url, table_id):
    response = requests.get(url)
    try:
        response.raise_for_status()
    except requests.exceptions.HTTPError as e:
        raise requests.exceptions.HTTPError(f'HTTP error occurred: {e}')

    soup = BeautifulSoup(response.content, 'html.parser')
    table = soup.find('table', id=table_id)
    if not table:
        raise ValueError("Table with the specified ID not found.")

    rows = table.find_all('tr')
    if not rows:
        return pd.DataFrame()

    headers = [header.get_text(strip=True) for header in rows[0].find_all(['th', 'td'])]
    data = [[td.get_text(strip=True) for td in row.find_all(['th', 'td'])] for row in rows[1:]]

    df = pd.DataFrame(data, columns=headers)
    return df

