def task_func(directory):
    import ast
    import os
    import glob

    dictionaries = []

    # Get all text files in the specified directory
    files = glob.glob(os.path.join(directory, '*.txt'))

    for file in files:
        with open(file, 'r', encoding='utf-8') as f:
            content = f.read()
            try:
                # Evaluate the string content to a dictionary
                dictionary = ast.literal_eval(content)
                if isinstance(dictionary, dict):
                    dictionaries.append(dictionary)
                else:
                    raise ValueError(f"File {file} does not contain a valid dictionary.")
            except (ValueError, SyntaxError):
                raise ValueError(f"File {file} contains invalid dictionary representation.")

    return dictionaries

