import subprocess
import os
import time
import glob

def task_func(r_script_path: str, output_path: str, duration: int) -> (bool, str):
    try:
        # Execute the R script using subprocess
        subprocess.run(['Rscript', r_script_path], check=True)

        # Measure the time taken to generate the output
        start_time = time.time()
        file_generated = False

        while time.time() - start_time < duration:
            # Use glob to check if any CSV files are present in the output directory
            if glob.glob(os.path.join(output_path, '*.csv')):
                file_generated = True
                break
            time.sleep(1)  # Wait for a short duration before checking again

        if file_generated:
            return (True, 'File generated successfully within the specified duration.')
        else:
            return (False, 'File not generated within the specified duration.')
    except subprocess.CalledProcessError:
        return (False, 'R script execution failed.')

